// RSS feed URLs — mirrors the app's .env RSS_FEEDS config
const feeds = [
  'https://techcrunch.com/category/artificial-intelligence/feed/',
  'https://feeds.arstechnica.com/arstechnica/technology-lab',
  'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml'
];

return feeds.map(url => ({ json: { feedUrl: url } }));

const SOURCE_MAP = {
  'techcrunch.com': 'TechCrunch',
  'arstechnica.com': 'Ars Technica',
  'theverge.com': 'The Verge'
};

function extractSourceName(url) {
  for (const [domain, name] of Object.entries(SOURCE_MAP)) {
    if (url.includes(domain)) return name;
  }
  try { return new URL(url).hostname; } catch { return 'Unknown'; }
}

function stripHtml(text) {
  if (!text) return '';
  return text.replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const url = (data.link || data.guid || '').trim();
  if (!url) continue;

  results.push({
    json: {
      title: (data.title || 'Untitled').trim(),
      url,
      source: extractSourceName(url),
      published_at: data.isoDate || data.pubDate || new Date().toISOString(),
      category: 'ai',
      summary: stripHtml(data.contentSnippet || data.summary || '').slice(0, 500) || null,
      content: stripHtml(data['content:encoded'] || data.content || '') || null
    }
  });
}

return results;

// Same markdown format as workflow 02 (Generate Markdown Digest). Pipeline has no topic/range params → "Last 1 week".
const articles = $input.all().map(i => i.json).filter(a => a.id || a.title);

function formatDate(date) {
  return new Date(date).toLocaleDateString('en-US', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
}

function formatDateShort(date) {
  return new Date(date).toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric'
  });
}

const endDate = new Date();
const startDate = new Date();
startDate.setDate(startDate.getDate() - 7);
const rangeLabel = 'Last 1 week';

const lines = [];
lines.push('# 📰 AI News Weekly Digest — ' + rangeLabel);
lines.push('');
lines.push(`**${formatDate(startDate)} — ${formatDate(endDate)}**`);
lines.push('');
const uniqueSources = new Set(articles.map(a => a.source));
lines.push(`> ${articles.length} articles from ${uniqueSources.size} sources`);
lines.push('');
lines.push('---');
lines.push('');

if (articles.length === 0) {
  lines.push('_No articles found for this period._');
} else {
  const grouped = {};
  for (const a of articles) {
    const cat = a.category || 'general';
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(a);
  }
  const sortedCategories = Object.entries(grouped).sort((a, b) => b[1].length - a[1].length);
  for (const [category, catArticles] of sortedCategories) {
    const displayCat = category.charAt(0).toUpperCase() + category.slice(1);
    lines.push(`## ${displayCat} (${catArticles.length})`);
    lines.push('');
    catArticles.sort((a, b) => new Date(b.published_at) - new Date(a.published_at));
    for (const a of catArticles) {
      const date = a.published_at ? formatDateShort(a.published_at) : 'Date N/A';
      const summary = a.summary ? (a.summary.slice(0, 200) + (a.summary.length > 200 ? '...' : '')) : '_No summary available._';
      lines.push(`### [${a.title}](${a.url})`);
      lines.push('');
      lines.push(`📅 ${date} · 📡 ${a.source}`);
      lines.push('');
      lines.push(summary);
      lines.push('');
    }
    lines.push('---');
    lines.push('');
  }
}
lines.push(`_Generated on ${formatDate(new Date())} by AI News Digest._`);

const markdown = lines.join('\n');

return [{
  json: {
    ingested: articles.length,
    indexed: 0,
    digest: { articleCount: articles.length, markdown }
  }
}];
